        const char *entry_path = archive_entry_pathname(entry);
        if (!entry_path || *entry_path == '\0') {
            archive_read_free_entry(src, entry);
            continue;
        }

        // Check for path traversal and invalid characters
        if (strchr(entry_path, '/') || strchr(entry_path, '\0') || strlen(entry_path) >= PATH_MAX) {
            archive_read_free_entry(src, entry);
            continue;
        }

        // Build full path safely
        snprintf(full_path, sizeof(full_path), "%s/%s", dest_path, entry_path);
