// Function to safely sanitize a filename
void sanitize_filename(const char *input, char *output, size_t output_size) {
    char *ptr = output;
    for (size_t i = 0; i < strlen(input) && ptr < output + output_size - 1; i++) {
        char c = input[i];
        if (c == '/' || c == '\0' || c == ':' || c == '*' || c == '?' || c == '"' || c == '<' || c == '>' || c == '|' || c == '\n' || c == '\r') {
            continue; // Skip dangerous characters
        }
        *ptr++ = c;
    }
    *ptr = '\0';
}

// Function to check if a path is within a given base directory
bool is_safe_path(const char *path, const char *base_dir) {
    char *path_copy = strdup(path);
    char *base_copy = strdup(base_dir);
    char *path_ptr = path_copy;
    char *base_ptr = base_copy;

    // Normalize paths
    char *normalized_path = realpath(path_copy, NULL);
    char *normalized_base = realpath(base_copy, NULL);

    if (!normalized_path || !normalized_base) {
        free(path_copy);
        free(base_copy);
        return false;
    }

    // Check if normalized path starts with normalized base
    if (strncmp(normalized_path, normalized_base, strlen(normalized_base)) != 0) {
        free(normalized_path);
        free(normalized_base);
        free(path_copy);
        free(base_copy);
        return false;
    }

    free(normalized_path);
    free(normalized_base);
    free(path_copy);
    free(base_copy);
    return true;
}

